// resAny reports unchecked method.
func resAny(m Sym) bool {
	n := sort.Search(len(resMethods), func(i int) bool { return resMethods[i] >= uint32(m) })
	return !(n < len(resMethods) && resMethods[n] == uint32(m))
}

// resOK checks result class.
func resOK(m Sym, id uint32) bool {
	v := uint64(m)<<32 | uint64(id)
	n := sort.Search(len(resPairs), func(i int) bool { return resPairs[i] >= v })
	return n < len(resPairs) && resPairs[n] == v
}
